package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.ToIntFunction;
import net.officefloor.hq.app.setting.DatedSetting;

/** A claim's due figure. */
public final class Dues {
    private Dues() {
    }

    /** What a late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own); the
     *  sheet's policy date (its today when blank), which decides how a claim's live figures round; and
     *  a claim's grace days (those of its person's grade in force on its date, as in force on it; 0: none); and
     *  the sheet's rounding mode by date (half-up or half-even; none: the policy date decides). */
    public record Late(DatedSetting pct, LocalDate today, LocalDate policy, ToIntFunction<Claim> grace, DatedSetting mode) {

        /** The date a claim's lateness counts from: its due-by plus its grace days. It is overdue once
         *  this is before the sheet's today. */
        public LocalDate lateFrom(Claim claim) {
            return LocalDate.parse(claim.getDueBy()).plusDays(grace.applyAsInt(claim));
        }

        /** How the live figures of a claim round by its round date ({@link Claim#getRoundDate}): by the
         *  rounding mode in force on it, else half up before the policy date, half to even on or after it. */
        public RoundingMode rounding(String roundDate) {
            String m = mode == null ? null : mode.on(roundDate);
            if ("half-up".equals(m)) return RoundingMode.HALF_UP;
            if ("half-even".equals(m)) return RoundingMode.HALF_EVEN;
            return LocalDate.parse(roundDate).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
        }
    }

    /** A claim's rate figure: an amount times a percent, divided by 100, rounded ({@code rounding}) to
     *  two decimals (no floor: that is applied last, by {@link #shown}). */
    public static String of(String amount, String pct, RoundingMode rounding) {
        return new BigDecimal(amount).multiply(new BigDecimal(pct))
                .divide(BigDecimal.valueOf(100), 2, rounding).toPlainString();
    }

    /** Whether a claim's amount makes it a correction: it is negative. */
    public static boolean isCorrection(String amount) {
        return new BigDecimal(amount).signum() < 0;
    }

    /** The late charge on a claim's figure: for each full 30 days its open (OPEN or PENDING) claim is past its
     *  due-by (fixed when it was added) plus its grace days on the sheet's today, the late percent in force on that
     *  boundary date (its due-by plus grace plus 30, 60, 90 ... days) of the figure plus the charges of
     *  the boundaries before it (compounding), each rounded by the policy date to two decimals, added up;
     *  none (0.00) when it is not overdue (a deferred claim never is), on a correction, or when it is waived. */
    public static BigDecimal charge(Claim claim, String figure, Late late) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        if (figure == null || isCorrection(claim.getAmount()) || !ClaimStatus.isOpen(claim.getStatus()) || claim.isDeferred() || claim.isWaived()) return total;
        LocalDate dueBy = late.lateFrom(claim);
        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
        RoundingMode rounding = late.rounding(claim.getRoundDate());
        for (long k = 1; k <= periods; k++) {
            String pct = late.pct().on(dueBy.plusDays(30 * k).toString());
            if (pct == null) continue;
            total = total.add(new BigDecimal(figure).add(total).multiply(new BigDecimal(pct))
                    .divide(BigDecimal.valueOf(100), 2, rounding));
        }
        return total;
    }

    /** The due a claim shows: the one fixed when settled, else its figure (bound by a statement, else
     *  {@code live}; null: none) with its late charge added on top, and at least {@code floor}, the sheet's
     *  floor in force on the claim's date (null: none), applied last (a correction has no floor). */
    public static String shown(Claim claim, String live, String floor, Late late) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        String figure = claim.due(live);
        if (figure == null) return null;
        BigDecimal due = new BigDecimal(figure).add(charge(claim, figure, late));
        if (floor != null && !isCorrection(claim.getAmount())) due = due.max(new BigDecimal(floor).setScale(2));
        return due.toPlainString();
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
 *  count live (open ones dated within a hold of theirs, and not bound, do not), n/a ones skipped, at most the sheet's cap; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force or dated on or before the sheet's today) on the sheet's today, and binds each counting claim
 *  to its rate figure under the due it shows now (its late charge and the floor are never bound); a claim that does not
 *  count live is unbound.
 *  <p>Taken as of a date ({@code asof}; blank: now) on or before the sheet's today, it goes by everything as it
 *  stood at the end of that date (every change made while the sheet's today was on or before it counts, every
 *  later one does not), that date standing in for the sheet's today: it records that day's due-total under that
 *  date and binds the claims that counted then to their figures then. Refused for a date after the sheet's
 *  today, or before the person was on the sheet. */
public class TakeStatement {
    public void take(@RequestParam(name = "asof", required = false) String asof, @Val Person person,
            PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate on = today;
        Person then = person;
        List<Claim> own;
        List<Rate> sheetRates;
        DatedSetting floor;
        Dues.Late late;
        BigDecimal cap;
        if (asof == null || asof.isBlank()) {
            own = claims.listOf(sheetId, person.getId());
            sheetRates = rates.list(sheetId);
            floor = settings.floor(sheetId);
            late = settings.late(sheetId, today);
            cap = settings.cap(sheetId);
        } else {
            try {
                on = LocalDate.parse(asof.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The statement date must be a date");
            }
            if (on.isAfter(today)) {
                throw new InvalidPersonException("The statement date cannot be after the sheet's today");
            }
            if (people.addedAfter(sheetId, person.getId(), on)) {
                throw new InvalidPersonException("The person was not on the sheet on the statement date");
            }
            then = people.findAsOf(sheetId, person.getId(), on);
            own = claims.listOfAsOf(sheetId, person.getId(), on);
            sheetRates = rates.listAsOf(sheetId, on);
            floor = settings.datedAsOf(sheetId, SettingRepository.FLOOR, SettingRepository.DEFAULT_FLOOR, on);
            late = settings.lateAsOf(sheetId, on);
            cap = settings.capAsOf(sheetId, on);
            person.setStatedAsOf(on.toString());
        }
        // The figure each counting claim is bound to, by claim id.
        Map<Long, String> figures = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        for (Claim c : own) {
            if (!then.countsLive(c)) continue;
            String grade = then.gradeOn(c.getDate());
            Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate(), c.getId());
            String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
            String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
            kept |= c.getSettledDue() != null || c.isBound()
                    || (rate != null && (!grade.equals(then.getGrade())
                            || !LocalDate.parse(c.getDate()).isAfter(on)));
            if (shown != null) total = total.add(new BigDecimal(shown));
            // The rate figure under it is bound; its late charge and floor keep following the sheet's today.
            figures.put(c.getId(), c.due(live));
        }
        for (Claim c : claims.listOf(sheetId, person.getId())) {
            if (figures.containsKey(c.getId())) c.bind(true, figures.get(c.getId()));
            else c.bind(false, null);
            claims.updateBinding(c);
        }
        boolean na = RateRepository.inForce(sheetRates, then.getGrade(), on.toString()) == null && !kept;
        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
        person.stated(na ? null : total.toPlainString(), on.toString(), figures.size());
        people.updateStatements(person);
    }
}
package net.officefloor.hq.app.claim;

